#include "gen_build.h"
#include "emit.h"
#include "../util/buffer.h"
#include <stdio.h>
#include <string.h>

int vmgen_gen_build(const vmgen_spec_t *spec, const char *output_dir) {
    char path[512];
    snprintf(path, sizeof(path), "%s/CMakeLists.txt", output_dir);

    vmgen_buf_t buf;
    vmgen_buf_init(&buf);

    vmgen_buf_appendf(&buf,
        "# Generated by vmgen for VM '%s' v%s\n"
        "cmake_minimum_required(VERSION 3.16)\n"
        "project(%s VERSION %s LANGUAGES C)\n\n"
        "set(CMAKE_C_STANDARD 11)\n"
        "set(CMAKE_C_STANDARD_REQUIRED ON)\n\n"
        "if(MSVC)\n"
        "    add_compile_options(/W4)\n"
        "    add_compile_definitions(_CRT_SECURE_NO_WARNINGS)\n"
        "else()\n"
        "    add_compile_options(-Wall -Wextra -Wpedantic)\n"
        "endif()\n\n",
        spec->name, spec->version, spec->name, spec->version);

    /* Library target with all generated sources */
    vmgen_buf_appendf(&buf,
        "add_library(%s_vm\n"
        "    vm.c\n"
        "    assembler.c\n"
        "    disasm.c\n"
        "    native.c\n",
        spec->name);

    if (spec->features.interned_strings) {
        vmgen_buf_append(&buf, "    strings.c\n");
    }

    if (spec->features.gc_enabled) {
        vmgen_buf_append(&buf, "    gc.c\n");
    }

    if (spec->features.closures) {
        vmgen_buf_append(&buf, "    closures.c\n");
    }

    if (spec->features.modules_enabled) {
        vmgen_buf_append(&buf, "    modules.c\n");
    }

    if (spec->features.coroutines) {
        vmgen_buf_append(&buf, "    fibers.c\n");
    }

    vmgen_buf_append(&buf, "    bytecode.c\n");

    vmgen_buf_appendf(&buf,
        ")\n\n"
        "target_include_directories(%s_vm PUBLIC ${CMAKE_CURRENT_SOURCE_DIR})\n\n",
        spec->name);

    /* Optional: example main that runs the VM */
    vmgen_buf_appendf(&buf,
        "# Example executable (uncomment and create main.c to use)\n"
        "# add_executable(%s_example main.c)\n"
        "# target_link_libraries(%s_example PRIVATE %s_vm)\n",
        spec->name, spec->name, spec->name);

    int rc = vmgen_buf_write_file(&buf, path);
    vmgen_buf_free(&buf);
    if (rc == 0) printf("vmgen: generated %s\n", path);
    return rc;
}
